// Turn the OCR JSON into one row per ingredient line for the price history sheet.
const file = $('Download Invoice File').first().json;

const raw = $input.first().json;
let text = raw.content ?? raw.text ?? raw.message?.content ?? '';
if (Array.isArray(text)) text = text.map(t => t.text || '').join('');

let invoice = {};
if (typeof text === 'object') {
  invoice = text;
} else {
  try { invoice = JSON.parse(String(text).replace(/```json|```/g, '').trim()); }
  catch (e) { throw new Error('Could not read invoice JSON from OCR step: ' + String(text).slice(0, 200)); }
}

const validUnits = ['kg', 'l', 'each'];
const date = /^\d{4}-\d{2}-\d{2}$/.test(invoice.invoice_date || '')
  ? invoice.invoice_date
  : new Date().toISOString().slice(0, 10);

return (invoice.lines || [])
  .filter(l => l.ingredient && Number(l.unit_price) > 0)
  .map(l => ({
    json: {
      invoice_date: date,
      supplier: invoice.supplier || 'Unknown supplier',
      invoice_number: invoice.invoice_number || '',
      item_on_invoice: l.item_on_invoice || '',
      ingredient: String(l.ingredient).trim().toLowerCase(),
      unit: validUnits.includes(String(l.unit).toLowerCase()) ? String(l.unit).toLowerCase() : 'each',
      unit_price: Number(Number(l.unit_price).toFixed(4)),
      source_file: file.name || ''
    }
  }));

// ---------- Settings ----------
const LOOKBACK_DAYS = 30;        // compare today's ingredient prices with prices from this many days ago
const MIN_MARGIN_DROP_PTS = 2;   // flag a dish when gross margin fell by at least this many points
const MAX_PRICE_INCREASE = 0.10; // never suggest more than +10% in one step
const PRICE_STEP = 0.50;         // round suggested prices up to this step (use 5 or 10 for INR)
const CHARM_ENDING = true;       // 13.50 -> 13.49 style endings (set false for INR)
// ------------------------------

const norm = s => String(s ?? '').trim().toLowerCase();
const num = v => Number(String(v ?? '').replace(/[^0-9.\-]/g, '')) || 0;
const round2 = v => Number(v.toFixed(2));
const DAY = 24 * 60 * 60 * 1000;
const today = new Date();
const cutoff = new Date(today.getTime() - LOOKBACK_DAYS * DAY);
const salesStart = new Date(today.getTime() - 7 * DAY);

const roundPrice = p => {
  let r = Math.ceil(p / PRICE_STEP) * PRICE_STEP;
  if (CHARM_ENDING) { r -= 0.01; if (r < p) r += PRICE_STEP; }
  return round2(r);
};

// 1. Ingredient price history -> current vs baseline price
const history = {};
for (const r of $('Read Ingredient Prices').all().map(i => i.json)) {
  const d = new Date(r.invoice_date);
  const p = num(r.unit_price);
  if (isNaN(d) || !p) continue;
  (history[norm(r.ingredient)] ??= []).push({ d, p });
}
const prices = {};
for (const [ing, list] of Object.entries(history)) {
  list.sort((a, b) => a.d - b.d);
  const current = list[list.length - 1];
  const older = list.filter(x => x.d <= cutoff);
  const baseline = older.length ? older[older.length - 1] : list[0];
  prices[ing] = {
    current: current.p,
    baseline: baseline.p,
    change_pct: baseline.p ? (current.p - baseline.p) / baseline.p : 0
  };
}

// 2. POS sales in the last 7 days
const sold = {};
for (const r of $('Read POS Sales').all().map(i => i.json)) {
  const d = new Date(r.date);
  if (isNaN(d) || d < salesStart) continue;
  sold[norm(r.dish)] = (sold[norm(r.dish)] || 0) + num(r.quantity_sold);
}

// 3. Recipe costing -> plate cost before vs now
const dishes = {};
const missing = new Set();
for (const r of $('Read Recipe Costing').all().map(i => i.json)) {
  const key = norm(r.dish);
  if (!key) continue;
  const dish = dishes[key] ??= { dish: r.dish, menu_price: 0, lines: [] };
  if (!dish.menu_price && num(r.menu_price)) dish.menu_price = num(r.menu_price);
  const p = prices[norm(r.ingredient)];
  if (!p) { missing.add(r.ingredient); continue; }
  const qty = num(r.quantity);
  dish.lines.push({
    ingredient: r.ingredient,
    before: qty * p.baseline,
    now: qty * p.current,
    change_pct: p.change_pct
  });
}

// 4. Flag dishes whose margin dropped because ingredients got pricier
const weekEnding = today.toISOString().slice(0, 10);
const flagged = [];
for (const d of Object.values(dishes)) {
  if (!d.menu_price || !d.lines.length) continue;
  const costBefore = d.lines.reduce((s, l) => s + l.before, 0);
  const costNow = d.lines.reduce((s, l) => s + l.now, 0);
  if (costNow <= costBefore) continue;

  const marginBefore = (d.menu_price - costBefore) / d.menu_price;
  const marginNow = (d.menu_price - costNow) / d.menu_price;
  const dropPts = (marginBefore - marginNow) * 100;
  if (dropPts < MIN_MARGIN_DROP_PTS || marginBefore >= 1) continue;

  const driver = d.lines.reduce((a, b) => (b.now - b.before) > (a.now - a.before) ? b : a);
  const restorePrice = costNow / (1 - marginBefore);
  const capped = Math.min(restorePrice, d.menu_price * (1 + MAX_PRICE_INCREASE));
  const units = sold[norm(d.dish)] || 0;

  flagged.push({
    week_ending: weekEnding,
    dish: d.dish,
    menu_price: round2(d.menu_price),
    cost_before: round2(costBefore),
    cost_now: round2(costNow),
    margin_before_pct: round2(marginBefore * 100),
    margin_now_pct: round2(marginNow * 100),
    margin_drop_pts: round2(dropPts),
    driver_ingredient: driver.ingredient,
    driver_price_change_pct: round2(driver.change_pct * 100),
    units_sold_7d: units,
    weekly_profit_leak: round2(units * (costNow - costBefore)),
    suggested_price: roundPrice(capped)
  });
}

flagged.sort((a, b) => b.weekly_profit_leak - a.weekly_profit_leak || b.margin_drop_pts - a.margin_drop_pts);

return [{
  json: {
    week_ending: weekEnding,
    dishes_checked: Object.keys(dishes).length,
    flagged_count: flagged.length,
    total_weekly_profit_leak: round2(flagged.reduce((s, f) => s + f.weekly_profit_leak, 0)),
    max_price_increase_pct: MAX_PRICE_INCREASE * 100,
    ingredients_without_price: [...missing],
    flagged
  }
}];
